export function resolveBrandLogoDataUri(props: any): string {
  if (!props) return BRAND_LOGO_DATA_URI;
  const direct =
    props.brandLogoDataUri ||
    props.brand_logo_data_uri ||
    props.thumbnail_spec?.brand_logo_data_uri;
  if (typeof direct === "string" && direct.startsWith("data:image/")) {
    return direct;
  }
  const chCandidates = [
    props.channel,
    props.channel_id,
    typeof props.channel_profile === "string" ? props.channel_profile : props.channel_profile?.id,
    props.thumbnail_spec?.channel_id,
  ].filter(Boolean);
  for (const raw of chCandidates) {
    const key = String(raw).trim().replace(/^ch_/, "");
    if (CHANNEL_BRAND_LOGOS[key]) return CHANNEL_BRAND_LOGOS[key];
  }
  const hookTitle = props.hook_title ? String(props.hook_title).trim() : "";
  if (hookTitle && TITLE_BRAND_LOGOS[hookTitle]) {
    return TITLE_BRAND_LOGOS[hookTitle];
  }
  const styleKey = props.visual_style_profile ? String(props.visual_style_profile).trim() : "";
  if (styleKey && STYLE_BRAND_LOGOS[styleKey]) {
    return STYLE_BRAND_LOGOS[styleKey];
  }
  return BRAND_LOGO_DATA_URI;
}
